	public static AnimationDefinition of(FuryAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case TALONS -> TALONS;
			case SHRIEK -> SHRIEK;
			case LASH -> LASH;
			case TEAR -> TEAR;
			case STAGGER -> STAGGER;
			case PHASE -> PHASE;
			case INTRO -> INTRO;
			case HURT -> HURT;
			case DEATH -> DEATH;
		};
	}

	/** Every animation, in FuryAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(FuryAnim.values()).map(FuryAnimations::of).toList();
	}
